-- Vigil Week 2: tabla de investigacion (generado desde lib/researchSeed.ts)
create table if not exists research_entries (
  id uuid primary key default gen_random_uuid(),
  slug text unique,
  kind text not null check (kind in ('example','competitor','mexico','risk','note')),
  title text not null,
  summary text not null,
  source_label text,
  source_url text,
  confidence text not null default 'media' check (confidence in ('alta','media','baja')),
  data jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

alter table research_entries enable row level security;

drop policy if exists "demo read research" on research_entries;
drop policy if exists "demo insert research" on research_entries;
drop policy if exists "demo delete notes" on research_entries;
create policy "demo read research" on research_entries for select to anon using (true);
create policy "demo insert research" on research_entries for insert to anon with check (kind = 'note');
create policy "demo delete notes" on research_entries for delete to anon using (kind = 'note');

on conflict (slug) do nothing;
