insert into research_entries (slug, kind, title, summary, source_label, source_url, confidence, data) values
  ('ex-salt-lake', 'example', 'Salt Lake City: respuesta verificada (2000)', 'La ciudad exigio verificar una alarma antes de enviar policia. La guia de POP Center reporta que las ciudades que lo adoptan reducen llamadas de alarma en torno al 90 % y que Salt Lake City gano el equivalente a cinco policias de tiempo completo. La guia no cita estudio para esas cifras.', 'POP Center — False Burglar Alarms, 2nd ed.', 'https://popcenter.asu.edu/problems/false_alarms/4', 'media', '{"lesson":"Verificar antes de despachar es la norma que Vigil debe respetar."}'::jsonb),
  ('ex-los-angeles', 'example', 'Los Angeles PD: reestructura de 2004', 'Tras reestructurar su politica en 2004, las llamadas y los despachos por alarma cayeron aproximadamente a la mitad. LAPD suspende el servicio despues de dos falsas alarmas en 12 meses.', 'POP Center — False Burglar Alarms, 2nd ed.', 'https://popcenter.asu.edu/problems/false_alarms/4', 'media', '{"lesson":"Las falsas alarmas tienen costo real: la policia deja de responder."}'::jsonb),
  ('ex-ecv', 'example', 'Verificacion mejorada por llamada (ECV)', 'Intentar contactar al duenio por dos o mas vias antes de llamar a la policia redujo las falsas alarmas entre 25 % y 40 %. En Montgomery County (Maryland, 2004) las empresas de alarmas cancelaron 24 % de las solicitudes de despacho.', 'POP Center — False Burglar Alarms, 2nd ed.', 'https://popcenter.asu.edu/problems/false_alarms/4', 'media', '{"lesson":"Este es el origen de la escalera de Vigil: primero tu, luego tus contactos."}'::jsonb),
  ('ex-noonlight', 'example', 'Noonlight: boton de seguridad con despacho de emergencia', 'App con boton de seguridad y respuesta de emergencia; gratis en Android, y en iOS la suscripcion agrega app de Apple Watch y respuesta automatica por choque. Ofrece APIs para que otras apps agreguen despacho y monitoreo profesional. Precio de las APIs: no publicado.', 'Noonlight Help Center', 'https://help.noonlight.com/en/articles/3270559-how-much-does-noonlight-cost', 'alta', '{"lesson":"El despacho humano se puede comprar como servicio; Vigil aun no lo hace."}'::jsonb),
  ('ex-wyze', 'example', 'Wyze Home Monitoring: monitoreo profesional barato (2020)', 'Wyze lanzo monitoreo profesional a US$5 al mes (US$60 al anio) el 10 de diciembre de 2020, operado con Noonlight y una central certificada TMA Five-Diamond. Una guia posterior lista Wyze en US$10 al mes: el precio cambio.', 'Security Sales & Integration', 'https://www.securitysales.com/news/wyze-pro-security-monitoring/122183/', 'media', '{"lesson":"Los precios de monitoreo bajan y cambian; el modelo no puede depender de un precio fijo."}'::jsonb),
  ('mx-alarmas-vecinales', 'mexico', 'Alarmas Vecinales CDMX (2014–2020)', 'Programa creado en 2014 por el gobierno de la CDMX. Dejo de operar en las 16 alcaldias el 3 de agosto de 2020 porque termino el contrato con la empresa. Lo sustituyo el boton de panico de ''Mi Calle'' en la App CDMX.', 'Eje Central', 'https://www.ejecentral.com.mx/programa-alarmas-vecinales-dejara-de-funcionar-en-la-cdmx?p=10', 'alta', '{"lesson":"Un programa de alarma comunitaria murio por depender de un solo contrato."}'::jsonb),
  ('mx-mi-alarma-en-casa', 'mexico', 'Mi Alarma en Casa (App CDMX)', 'Boton virtual en el celular que suena en el C2. Si el domicilio esta registrado y la persona esta en casa, el C2 envia patrulla; la propia autoridad lo presenta como complemento del 911, no sustituto, y los 3–4 minutos de llegada son estimacion oficial, no garantia.', 'Chilango (feb 2024)', 'https://www.chilango.com/ciudadania/mi-alarma-en-casa-de-app-cdmx-activa-el-boton-del-c2-desde-el-celular-en-caso-de-emergencia/', 'alta', '{"lesson":"En CDMX ya existe un canal oficial; Vigil debe mandar a la persona a ese canal."}'::jsonb),
  ('mx-robo-casa-2026', 'mexico', 'Robo a casa habitacion, enero–junio 2026', 'Denuncias: Estado de Mexico 1,559 (frente a 2,806 un anio antes, -44 %), Guanajuato 1,278, Ciudad de Mexico 1,113, Puebla 959, Hidalgo 841, Jalisco 835. La nota atribuye la baja de 44 % al SESNSP; no indica la fuente del ranking. Son denuncias, no delitos totales.', 'Posta Mexico', 'https://www.posta.com.mx/edomex/edomex-encabeza-lista-nacional-en-robo-a-casa-habitacion/vl2235886', 'media', '{"lesson":"El problema existe en la zona de los primeros usuarios (CDMX / Edomex)."}'::jsonb),
  ('mx-mercado-2015', 'mexico', 'Mercado de alarmas en hogares (dato de 2015)', 'AMAI: 14.2 % de los hogares mexicanos (4.06 millones) tenia sistema de seguridad avanzado; monitoreo de 250 a 700 pesos al mes. Dato de hace mas de diez anios: sirve como orden de magnitud, no como cifra actual.', 'El Financiero (ago 2015)', 'https://www.elfinanciero.com.mx/empresas/uno-de-cada-10-hogares-tiene-sistema-antirrobo/', 'baja', '{"lesson":"Existe disposicion a pagar mensualidad, pero el dato esta viejo."}'::jsonb),
  ('cp-ring', 'competitor', 'Ring Alarm', 'Sistema DIY con plan de monitoreo profesional. Las camaras son opcionales. En Mexico se venden dispositivos Ring en Amazon y Mercado Libre; monitoreo profesional en Mexico: no verificado.', 'Tom''s Guide / Xataka Mexico', 'https://www.tomsguide.com/us/best-diy-security-system,review-5591.html', 'baja', '{"price":"US$10–20/mes (la fuente se contradice)","camera":"opcional","region":"EE. UU.; equipo en MX","status":"activo","model":"Hardware + suscripcion"}'::jsonb),
  ('cp-simplisafe', 'competitor', 'SimpliSafe', 'Monitoreo profesional por niveles. Camaras no requeridas salvo para la proteccion exterior con IA de los niveles Pro. La misma guia da dos juegos de precios distintos.', 'Tom''s Guide', 'https://www.tomsguide.com/us/best-diy-security-system,review-5591.html', 'baja', '{"price":"US$15–50/mes (o US$22–80 segun otra tabla)","camera":"no","region":"EE. UU.","status":"activo","model":"Hardware + suscripcion"}'::jsonb),
  ('cp-abode', 'competitor', 'Abode', 'Plan gratis, Standard (US$69/anio) y Pro con monitoreo profesional (US$229/anio). Monitoreo por periodos cortos como complemento.', 'Tom''s Guide', 'https://www.tomsguide.com/us/best-diy-security-system,review-5591.html', 'media', '{"price":"US$229/anio (Pro)","camera":"opcional","region":"EE. UU.","status":"activo","model":"Freemium + suscripcion"}'::jsonb),
  ('cp-wyze', 'competitor', 'Wyze Home Monitoring', 'Un solo plan de monitoreo profesional, sin respaldo celular. El kit inicial no trae camara. Lanzo a US$5/mes en 2020; una guia reciente lo lista en US$10/mes.', 'Tom''s Guide / Security Sales', 'https://www.securitysales.com/news/wyze-pro-security-monitoring/122183/', 'media', '{"price":"US$10/mes o US$100/anio","camera":"opcional","region":"EE. UU.","status":"activo","model":"Hardware + suscripcion"}'::jsonb),
  ('cp-noonlight', 'competitor', 'Noonlight', 'Protege a la persona, no a la casa: boton de seguridad con despacho. Gratis en Android; la suscripcion de iOS agrega funciones. Sin camaras.', 'Noonlight Help Center', 'https://help.noonlight.com/en/articles/3270559-how-much-does-noonlight-cost', 'alta', '{"price":"Gratis; iOS de pago (monto no publicado)","camera":"no","region":"EE. UU.","status":"activo","model":"Freemium"}'::jsonb),
  ('cp-mi-alarma', 'competitor', 'Mi Alarma en Casa (gobierno CDMX)', 'Canal oficial gratuito dentro de la App CDMX. Costo: la fuente no lo indica. Requiere registrar domicilio y cuenta Llave; solo cubre CDMX.', 'Chilango', 'https://www.chilango.com/ciudadania/mi-alarma-en-casa-de-app-cdmx-activa-el-boton-del-c2-desde-el-celular-en-caso-de-emergencia/', 'alta', '{"price":"No indicado por la fuente","camera":"no","region":"CDMX","status":"activo","model":"Servicio publico"}'::jsonb),
  ('cp-alarmas-vecinales', 'competitor', 'Alarmas Vecinales (CDMX)', 'Alarmas comunitarias del gobierno de la CDMX. Terminaron el 3 de agosto de 2020 al vencer el contrato.', 'Eje Central', 'https://www.ejecentral.com.mx/programa-alarmas-vecinales-dejara-de-funcionar-en-la-cdmx?p=10', 'alta', '{"price":"No indicado por la fuente","camera":"no","region":"CDMX","status":"descontinuado","model":"Servicio publico"}'::jsonb),
  ('cp-monitoreo-mx', 'competitor', 'Monitoreo privado tradicional (Mexico)', 'Empresas locales de alarma con monitoreo. Rango de 2015: 250–700 pesos al mes, equipo aparte o incluido. No se verificaron precios actuales de Verisure ni Prosegur en Mexico.', 'El Financiero (2015)', 'https://www.elfinanciero.com.mx/empresas/uno-de-cada-10-hogares-tiene-sistema-antirrobo/', 'baja', '{"price":"MXN 250–700/mes (2015)","camera":"opcional","region":"Mexico","status":"activo","model":"Contrato de servicio"}'::jsonb),
  ('rk-auto911', 'risk', 'Llamar a emergencias automaticamente', 'Muchas jurisdicciones castigan o suspenden la respuesta tras falsas alarmas (LAPD: dos en 12 meses). Por eso Vigil no marca solo: al final de la escalera una persona recibe la instruccion de llamar.', 'POP Center', 'https://popcenter.asu.edu/problems/false_alarms/4', 'media', '{"likelihood":4,"impact":5,"mitigation":"Entrega a una persona; nunca marcado automatico."}'::jsonb),
  ('rk-falsas', 'risk', 'Falsas alarmas que cansan a los contactos', 'Si los contactos reciben alertas falsas, dejan de responder. El boton ''Estoy bien'' corta la escalera antes del Tier 2.', 'Prueba propia (Week 1)', null, 'media', '{"likelihood":4,"impact":4,"mitigation":"Ventana de confirmacion del duenio antes de avisar a otros."}'::jsonb),
  ('rk-simulado', 'risk', 'Las notificaciones son solo simuladas', 'Ningun SMS ni llamada sale de verdad. Cada aviso esta marcado ''Simulado — no enviado''. Enviar reales requiere proveedores con costo y aprobacion.', 'Estado actual del prototipo', null, 'alta', '{"likelihood":5,"impact":3,"mitigation":"Etiqueta visible y declaracion en el pie de pagina."}'::jsonb),
  ('rk-pestana', 'risk', 'La escalera solo avanza con la pagina abierta', 'Hallazgo real de Week 1: el nivel se calcula al leer, pero las filas de alert_log solo se escriben mientras la pagina esta abierta. Una version real necesita un proceso en servidor.', 'Iteration log de Week 1', null, 'alta', '{"likelihood":5,"impact":4,"mitigation":"Documentado; fase siguiente: escalamiento en servidor."}'::jsonb),
  ('rk-rls', 'risk', 'Base de datos abierta a cualquiera (solo demo)', 'Las politicas RLS permiten lectura y escritura anonima para que la demo funcione. Con datos reales de contactos esto seria inaceptable.', 'sql/week1.sql', null, 'alta', '{"likelihood":5,"impact":4,"mitigation":"Contactos ficticios; autenticacion y RLS por usuario antes de datos reales."}'::jsonb),
  ('rk-contactos', 'risk', 'Los contactos no aceptan el rol', 'Nadie ha preguntado a un posible contacto de confianza si querria recibir estas alertas. Es una suposicion sin validar.', 'Pendiente: conversacion de validacion', null, 'baja', '{"likelihood":3,"impact":4,"mitigation":"Entrevista real con una persona antes de Week 3."}'::jsonb),
  ('rk-proveedor', 'risk', 'Depender de un solo proveedor o contrato', 'Alarmas Vecinales termino al vencer un contrato. Vigil depende de Supabase y Vercel gratuitos: Supabase pausa proyectos inactivos a los 7 dias.', 'Eje Central; experiencia propia (Week 1)', 'https://www.ejecentral.com.mx/programa-alarmas-vecinales-dejara-de-funcionar-en-la-cdmx?p=10', 'media', '{"likelihood":3,"impact":3,"mitigation":"Respaldo con datos locales y revision semanal del proyecto."}'::jsonb)
